-- ======================================================================
-- Delete all old passages, keep only the 15 new authentic PYQ passages
-- Also recategorize some for CGL DEST support
-- ======================================================================

-- Soft-delete all passages that are NOT the 15 new exam-length PYQ passages
UPDATE passages SET is_active = false
WHERE id NOT IN (
  'a0000000-0000-0000-0000-000000000200',
  'a0000000-0000-0000-0000-000000000201',
  'a0000000-0000-0000-0000-000000000202',
  'a0000000-0000-0000-0000-000000000203',
  'a0000000-0000-0000-0000-000000000204',
  'a0000000-0000-0000-0000-000000000205',
  'a0000000-0000-0000-0000-000000000206',
  'a0000000-0000-0000-0000-000000000207',
  'a0000000-0000-0000-0000-000000000208',
  'a0000000-0000-0000-0000-000000000209',
  'a0000000-0000-0000-0000-000000000210',
  'a0000000-0000-0000-0000-000000000211',
  'a0000000-0000-0000-0000-000000000212',
  'a0000000-0000-0000-0000-000000000213'
);

-- Assign some CHSL passages as also usable for CGL DEST mode
-- CGL DEST typically has data-entry/economy/govt passages
UPDATE passages SET category = 'ssc_cgl'
WHERE id IN (
  'a0000000-0000-0000-0000-000000000204',  -- Financial Inclusion
  'a0000000-0000-0000-0000-000000000206',  -- Infrastructure Development
  'a0000000-0000-0000-0000-000000000209',  -- Agricultural Reforms
  'a0000000-0000-0000-0000-000000000213'   -- Startup Ecosystem
);

-- Tag all as exam-length
UPDATE passages SET is_exam_length = true
WHERE id IN (
  'a0000000-0000-0000-0000-000000000200',
  'a0000000-0000-0000-0000-000000000201',
  'a0000000-0000-0000-0000-000000000202',
  'a0000000-0000-0000-0000-000000000203',
  'a0000000-0000-0000-0000-000000000204',
  'a0000000-0000-0000-0000-000000000205',
  'a0000000-0000-0000-0000-000000000206',
  'a0000000-0000-0000-0000-000000000207',
  'a0000000-0000-0000-0000-000000000208',
  'a0000000-0000-0000-0000-000000000209',
  'a0000000-0000-0000-0000-000000000210',
  'a0000000-0000-0000-0000-000000000211',
  'a0000000-0000-0000-0000-000000000212',
  'a0000000-0000-0000-0000-000000000213'
);
